import{_ as s}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as d,o as e,ag as i,G as l}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"网易UU远程上手教程","description":"网易UU远程是一款远程控制软件：人不在电脑旁边，也能用手机、平板或另一台电脑看到它的屏幕、操作它、取它的文件。本页带你装好两端，用「设备 ID + 验证码」连上第一台电脑，再学会无人值守、远程开机、文件传输与防窥。","frontmatter":{"title":"网易UU远程上手教程","description":"网易UU远程是一款远程控制软件：人不在电脑旁边，也能用手机、平板或另一台电脑看到它的屏幕、操作它、取它的文件。本页带你装好两端，用「设备 ID + 验证码」连上第一台电脑，再学会无人值守、远程开机、文件传输与防窥。","domain":"product","tags":["remote-control","remote-desktop","netease"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/uu-remote/uu-remote.md","filePath":"zh/products/uu-remote/uu-remote.md","lastUpdated":1795764761000}'),n={name:"zh/products/uu-remote/uu-remote.md"};function h(o,t,p,k,c,g){const a=r("DocDiagram");return e(),d("div",null,[t[0]||(t[0]=i("",48)),l(a,{src:"/diagrams/uu-remote-connect.svg",alt:"这张时序图按编号回答一个问题：你在主控端输入设备 ID 和验证码之后，画面和操作是怎样在两台设备之间来回的。图里有三个对象：主控端，就是你手里操作的设备；被控端，就是被远程操作的那台电脑；网易的服务，只画成一个框。第一步，主控端把被控端的设备 ID 与验证码发给网易的服务。第二步，网易的服务校验身份并建连；这一步的内部流程官方未公开，图里只有一个框，没有画怎么校验，也没有画数据走直连还是中转。建连完成后，两端开始收发数据。第三步，被控端把采集到的画面与声音编码成数据流，持续传送给主控端，这是数据量大的下行。第四步，主控端把键盘、鼠标、触控等操作事件发给被控端，这是数据量小的上行。第五步，被控端执行这些操作，屏幕内容变化，然后回到第三步继续同步。第三步到第五步每次操作都会重复。第三步和第四步的两条数据流画在一个虚线框里，表示官方称两端之间是端到端加密；具体的加密算法、编解码器、传输协议、端口和时延，官方都没有公开，图里也没有画。主控端这一侧做的事是解码并显示画面、播放声音，以及采集你的键鼠与触控输入；被控端这一侧做的事是采集屏幕画面与声音，以及执行操作。",width:1020}),t[1]||(t[1]=i("",118))])}const f=s(n,[["render",h]]);export{m as __pageData,f as default};
